export function parseCsv(text: string): string[][] {
  const rows: string[][] = [];
  let row: string[] = [];
  let field = "";
  let quoted = false;
  let rowHasContent = false;

  const endRow = () => {
    row.push(field);
    if (rowHasContent) rows.push(row);
    row = [];
    field = "";
    rowHasContent = false;
  };

  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    if (quoted) {
      if (char !== '"') field += char;
      else if (text[i + 1] === '"') {
        field += '"';
        i++;
      } else quoted = false;
      continue;
    }
    if (char === '"' && field === "") {
      quoted = true;
      rowHasContent = true;
    } else if (char === ",") {
      row.push(field);
      field = "";
      rowHasContent = true;
    } else if (char === "\n") {
      endRow();
    } else if (char === "\r" && text[i + 1] === "\n") {
      endRow();
      i++;
    } else {
      field += char;
      rowHasContent = true;
    }
  }
  endRow();
  return rows;
}
EOF
cat > src/money.ts <<'EOF'
const AMOUNT = /^(-?)(\d+|\d{1,3}(?:,\d{3})+)(?:\.(\d{1,2}))?$/;

export function parseAmount(raw: string): number {
  const match = AMOUNT.exec(raw);
  if (!match) throw new Error(`invalid amount: ${JSON.stringify(raw)}`);
  const [, sign, integer, fraction = ""] = match;
  const cents = Number(integer.replaceAll(",", "")) * 100 + Number(fraction.padEnd(2, "0"));
  if (!Number.isSafeInteger(cents)) throw new Error(`amount out of range: ${raw}`);
  return sign === "-" && cents !== 0 ? -cents : cents;
}

export function formatCents(cents: number): string {
  const sign = cents < 0 ? "-" : "";
  const abs = Math.abs(cents);
  const fraction = String(abs % 100).padStart(2, "0");
  return `${sign}${Math.floor(abs / 100)}.${fraction}`;
}
EOF
cat > src/report.ts <<'EOF'
import { parseCsv } from "./csv";
import { parseAmount } from "./money";

export type Summary = {
  totals: Map<string, number>;
  skipped: number;
};

export function summarize(csvText: string): Summary {
  const rows = parseCsv(csvText).slice(1);
  const totals = new Map<string, number>();
  let skipped = 0;
  for (const row of rows) {
    const cents = row.length === 4 ? tryParseAmount(row[3]) : undefined;
    if (cents === undefined) {
      skipped++;
      continue;
    }
    const category = row[1].trim();
    totals.set(category, (totals.get(category) ?? 0) + cents);
  }
  return { totals, skipped };
}

function tryParseAmount(raw: string): number | undefined {
  try {
    return parseAmount(raw);
  } catch {
    return undefined;
  }
}
EOF
cat > src/cli.ts <<'EOF'
import { formatCents } from "./money";
import { summarize } from "./report";

const path = process.argv[2];
if (path === undefined) {
  console.error("usage: bun src/cli.ts <file.csv>");
  process.exit(2);
}

let text: string;
try {
  text = await Bun.file(path).text();
} catch {
  console.error(`error: cannot read ${path}`);
  process.exit(1);
}

const { totals, skipped } = summarize(text);
const entries = [...totals].sort(
  ([nameA, totalA], [nameB, totalB]) => totalB - totalA || (nameA < nameB ? -1 : nameA > nameB ? 1 : 0),
);
let grandTotal = 0;
const lines: string[] = [];
for (const [category, total] of entries) {
  grandTotal += total;
  lines.push(`${category}\t${formatCents(total)}`);
}
lines.push(`TOTAL\t${formatCents(grandTotal)}`);
console.log(lines.join("\n"));
if (skipped > 0) console.error(`skipped: ${skipped}`);
EOF
