export function parseCsv(text: string): string[][] {
  const rows: string[][] = [];
  let row: string[] = [];
  let field = "";
  let quoted = false;
  let rowHasContent = false;

  const endRow = () => {
    row.push(field);
    if (rowHasContent) rows.push(row);
    row = [];
    field = "";
    rowHasContent = false;
  };

  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    if (quoted) {
      if (char !== '"') field += char;
      else if (text[i + 1] === '"') {
        field += '"';
        i++;
      } else quoted = false;
      continue;
    }
    if (char === '"' && field === "") {
      quoted = true;
      rowHasContent = true;
    } else if (char === ",") {
      row.push(field);
      field = "";
      rowHasContent = true;
    } else if (char === "\n") {
      endRow();
    } else if (char === "\r" && text[i + 1] === "\n") {
      endRow();
      i++;
    } else {
      field += char;
      rowHasContent = true;
    }
  }
  endRow();
  return rows;
}
